mapper.select:
select count(1) from t_delivery_print_log
where customer_id = #{customerId}
  and delivery_date = #{deliveryDate}

    and customer_dept_id = #{customerDeptId}
    and customer_dept_id is null

select id, customer_id, delivery_date, customer_dept_id, print_time, print_by, template_id, create_by, create_time
from t_delivery_print_log

    and customer_id = #{customerId}
    and delivery_date = #{deliveryDate}
    and customer_dept_id = #{customerDeptId}

order by print_time desc, id desc
